/**
 * factionCandidate — shared `FactionCandidate` -> `WizardFactionDraft`
 * mapping (#1724 Task 11).
 *
 * Lifted out of `StepFactions.tsx` (previously a private, unexported
 * `candidateToFactionDraft`) so the manual AI-discovery accept path
 * (StepFactions) and the ODIN-grounded generation completion path
 * (ExerciseSetupWizardRoute) can never drift apart on the `origin` backfill
 * or the `reasoning`/`confidence` carry-through that `sanitizeFactions`
 * (`useWizardDraft.ts`) relies on to classify a faction as "discovered"
 * rather than "manual" on read. Both call sites must produce byte-identical
 * `WizardFactionDraft` shapes for the same `FactionCandidate` input.
 */

import type { FactionCandidate } from "../api/factions";
import type { WizardFactionDraft } from "./types";

/** Convert an accepted AI candidate to the persisted WizardFactionDraft shape. */
export function candidateToFactionDraft(c: FactionCandidate): WizardFactionDraft {
  return {
    name: c.name,
    color: c.color || undefined,
    description: c.description || undefined,
    beliefs: [...c.stance_keywords],
    influence: c.influence,
    activityLevel: c.activity_level,
    profileCount: c.profile_count,
    allies: [...c.allies],
    adversaries: [...c.adversaries],
    reasoning: c.reasoning,
    confidence: c.confidence,
    origin: "discovered",
  };
}


--- frontends/range-mfe/src/wizard/odinPrefill.ts (171 lines) ---
/**
 * Shared ODIN scalar-prefill logic (#1724 exercise: "Use this environment"
 * bug fix). Lifted out of `ExerciseSetupWizardRoute.tsx` (where it was
 * defined and used solely by the "Generate & Apply" completion patch) so BOTH
 * ODIN entry paths — "Use this environment" (`onSelectTemplate`) and
 * "Generate & Apply" (`applyGenerationResult`) — build their scalar half from
 * the exact same code and cannot drift.
 *
 * Product decision (live design review, #1724 exercise): "Use this
 * environment" must prefill the setting WITHOUT running the AI — i.e. apply
 * everything Generate & Apply writes EXCEPT the AI-generated factions and the
 * environment analysis. `odinScenarioPatch` below is that shared "everything
 * except factions/analysis" half.
 */

import type { OdinTemplateDetail } from "../api/odin";
import { codeFromName } from "../lib/countries";
import type { WizardDraftPatch } from "./useWizardDraft";
import { DESCRIPTION_MAX } from "./types";

/** English-key-suffix objective category fallback (mirrors the wizard's own
 * `OBJECTIVE_CATEGORIES` convention in StepLocationObjective.tsx — the
 * PERSISTED value is always one of those locale-stable English strings, never
 * a raw backend token). Matches the semantic category range-svc's own
 * grounding fallback derives (`information_operations`) for an OE the
 * instructor hasn't supplied an objective for. */
const ODIN_GENERATE_FALLBACK_OBJECTIVE_CATEGORY = "Information operations";

/**
 * Collapse every whitespace run to a single space. ODIN's scraped infobox
 * values carry the source table's own column padding ("Donovians   80%",
 * "Kalmyk    Karachay-Balkar") and embedded newlines; pasted verbatim into a
 * prose sentence those read as broken text.
 */
function normalizeWhitespace(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

/**
 * Truncate to `max` characters on a word boundary, appending an ellipsis
 * only when something was actually dropped. `DESCRIPTION_MAX` is the field's
 * own ceiling (see its doc in ./types) and `maxLength` does not apply to a
 * programmatic prefill, so this function is what keeps the two in agreement.
 */
function truncateToWord(value: string, max: number): string {
  if (value.length <= max) return value;
  const hard = value.slice(0, max - 1);
  const lastSpace = hard.lastIndexOf(" ");
  // A single unbroken token longer than the field takes the hard cut.
  const body = lastSpace > 0 ? hard.slice(0, lastSpace) : hard;
  return `${body.replace(/[\s,;:.\u2014-]+$/, "")}\u2026`;
}

/**
 * Derive the wizard-prefill scalars (#1724 Task 11 binding requirement 3)
 * from the ALREADY-FETCHED ODIN template detail — the same read path the
 * preview drawer itself uses (`useOdinTemplateDetail`), so no new prefill
 * plumbing is introduced. Mirrors range-svc's own grounding-fallback
 * derivation of the OE title/official name and capital closely enough that
 * what the wizard shows the instructor matches what actually grounded the
 * run, without either side importing the other's code.
 *
 * `description` is the deliberate exception to that mirroring — see the
 * comment on its own derivation below. range-svc's `_derive_description`
 * builds LLM grounding material; this one builds a briefing line a person
 * reads inside a 600-character textarea.
 */
export function buildOdinScenarioFields(detail: OdinTemplateDetail): {
  readonly name: string;
  readonly description: string;
  readonly country: string;
  readonly city: string;
  readonly objective: string;
  readonly objectiveCategory: string;
} {
  const name = detail.card.name;
  const country = detail.official_name !== "" ? detail.official_name : name;
  const city = detail.capital;
  const objective =
    country !== ""
      ? `Understand and shape the information environment in ${country}.`
      : "Understand and shape the information environment.";
  // A one-sentence briefing summary, NOT a fact dump. The field's own
  // placeholder promises "a 1-2 sentence summary participants will see in the
  // briefing", and this used to emit a clause-per-fact render of all five
  // infobox facts instead — for Donovia that is 669 characters of
  // "Government: ... Population: ... Official languages: <25 entries>. Major
  // ethnic groups: <12 entries>", over a 600-character field, padded with the
  // source table's own column whitespace.
  //
  // So only the three SHORT scalars ride this sentence. The two enumerations
  // (`official_languages`, `ethnic_groups`) are dropped deliberately, not
  // forgotten: they are already on the preview drawer's own fact grid and in
  // the ODIN article context documents `useOdinContextDocuments` attaches, and
  // neither belongs in a participant-facing briefing line.
  //
  // This is the one place that deliberately DIVERGES from range-svc's
  // `_derive_description` (workers/generation/odin_exercise/grounding.py),
  // which the rest of this module mirrors. That function's output is LLM
  // grounding material, where exhaustive facts genuinely help; this string is
  // read by a person in a capped textarea. Same source facts, different
  // consumer, so do not "re-sync" the two.
  const summaryFacts: string[] = [];
  if (detail.government !== "") {
    summaryFacts.push(normalizeWhitespace(detail.government));
  }
  if (detail.population !== "") {
    summaryFacts.push(`population ${normalizeWhitespace(detail.population)}`);
  }
  if (city !== "") summaryFacts.push(`capital ${normalizeWhitespace(city)}`);
  const head = `${normalizeWhitespace(name)} operational environment`;
  const description = truncateToWord(
    summaryFacts.length > 0
      ? `${head} \u2014 ${summaryFacts.join(", ")}.`
      : `${head}.`,
    DESCRIPTION_MAX,
  );
  return {
    name,
    description,
    country,
    city,
    objective,
    objectiveCategory: ODIN_GENERATE_FALLBACK_OBJECTIVE_CATEGORY,
  };
}

/**
 * The shared scalar half of BOTH ODIN prefill paths ("Use this environment"
 * and "Generate & Apply", #1724 exercise). Sets everything Generate & Apply
 * writes to the draft EXCEPT the AI-generated `factions` and the environment
 * `analysisDone`/draft-id bookkeeping — those stay Generate & Apply's own
 * job, applied only alongside this patch, never by it.
 *
 * `region`/`regionCode` are deliberately blanked, never carried from ODIN's
 * own `region` (a combatant-command band — `africa`, `indo_pacific`, … — not
 * a sub-national region): writing it would make `isRegionProvablyInvalid`
 * true, blocking the Location step's forward-nav and the launch backstop.
 *
 * `countryCode` legitimately resolves to `""` for a fictional DATE
 * environment (Olvana, Atropia, Donovia) that `codeFromName` cannot match —
 * that is expected and harmless, since `isCountryMissing` only checks that
 * `country` itself is non-empty.
 *
 * Sets `odinPrefill: true` in this SAME patch — the two ODIN paths are the
 * only writers of that field, and only when these scalars actually landed.
 */
export function odinScenarioPatch(
  detail: OdinTemplateDetail,
  templateId: string,
  templateName: string,
): WizardDraftPatch {
  const scenario = buildOdinScenarioFields(detail);
  return {
    name: scenario.name,
    description: scenario.description,
    country: scenario.country,
    city: scenario.city,
    countryCode: codeFromName(scenario.country) ?? "",
    region: "",
    regionCode: null,
    objective: scenario.objective,
    objectiveCategory: scenario.objectiveCategory,
    templateId,
    templateName,
    templateSource: "odin",
    configMethod: "template",
    odinPrefill: true,
  };
}


--- frontends/range-mfe/src/wizard/stepState.ts (200 lines) ---
/**
 * stepState — the wizard's step-completion model, shared by the route (the
 * forward-nav gate and the launch backstop) and the nav rail (WizardNav).
 *
 * It lives outside `routes/` on purpose: WizardNav imports it, and a component
 * must never reach into a route module. Everything here is keyed by the step's
 * stable `id`, never by a bare index literal, so inserting a step into
 * WIZARD_STEPS cannot silently re-point a rule at the wrong step (the index →
 * id resolution happens in exactly one place: `stepIdAt`).
 */

import {
  isCategoryMissing,
  isCountryMissing,
  isObjectiveTooShort,
  validateExerciseFields,
} from "../components/exerciseForm";
import { isRegionProvablyInvalid } from "../lib/locationMatch";
import { WIZARD_STEPS, type WizardDraft, type WizardStep } from "./types";

/** The stable id of a wizard step. */
export type WizardStepId = WizardStep["id"];

/**
 * StepBasics holds the wizard's only required fields (name + the
 * both-or-neither date range). The forward-nav gate and the launch gate must
 * block on the SAME condition, so the check lives here to keep them in lockstep
 * (mirrors the standalone CreateExerciseForm's validateExerciseFields gate).
 */
export function basicsHasErrors(
  name: string,
  startDate: string,
  endDate: string,
): boolean {
  const errors = validateExerciseFields({ name, startDate, endDate });
  return Boolean(errors.name || errors.dates);
}

/**
 * Baseline generation ON with an empty website selection would create an
 * exercise that generates baseline content from ZERO sources —
 * useCreateExerciseFromDraft skips BatchEnable entirely, so nothing surfaces the
 * problem afterwards. StepConfig's picker registers a Continue-interceptor for
 * this, but that seam only covers the footer Continue button: the nav rail and
 * "Create" go through the gate below instead, which is why the
 * requirement is repeated here as a draft-only check (#2126 follow-up).
 */
function isBaselineSelectionMissing(draft: WizardDraft): boolean {
  return draft.generateBaseline && draft.baselineWebsiteIds.length === 0;
}

/**
 * Per-step completion predicates, keyed by step id. Steps that persist nothing
 * (review) are complete-on-visit: there is no state that could make them
 * "unanswered". Config is the one exception among the pick-nothing steps: `configMethod` defaults to "wizard"
 * and `generateBaseline: false` is a valid final answer, but turning baseline
 * generation ON without choosing an outlet is an unfinished answer, not a
 * deliberate one (see `isBaselineSelectionMissing`).
 *
 * The config/location/objective entries are the SAME predicates the forward-nav
 * gate uses (see `stepForwardBlocked`), so the rail and the gate can never
 * disagree.
 */
const STEP_COMPLETE: Readonly<
  Record<WizardStepId, (draft: WizardDraft) => boolean>
> = {
  basics: (d) => !basicsHasErrors(d.name, d.startDate, d.endDate),
  config: (d) => !isBaselineSelectionMissing(d),
  location: (d) =>
    !isCountryMissing(d.country) &&
    !isRegionProvablyInvalid({ countryCode: d.countryCode, region: d.region }),
  objective: (d) =>
    !isObjectiveTooShort(d.objective) &&
    !isCategoryMissing(d.objectiveCategory),
  factions: (d) => d.factions.length > 0,
  analysis: (d) => d.analysisDone,
  timeline: (d) => d.timelineMode !== "",
  context: (d) => d.contextDocuments.length > 0,
  review: () => true,
};

/**
 * Per-step count accessors, keyed by step id. Only steps with something worth
 * badging in the nav rail get an entry — everything else is `undefined`. This
 * MUST agree with `STEP_COMPLETE`: factions counts `draft.factions.length`
 * only (never `draft.factionSuggestions`, which holds un-added AI candidates
 * that are not part of the exercise), the same field `STEP_COMPLETE.factions`
 * gates on.
 */
const STEP_COUNT: Readonly<
  Partial<Record<WizardStepId, (draft: WizardDraft) => number>>
> = {
  factions: (d) => d.factions.length,
};

/**
 * The badge-worthy count for step `id`, or undefined when the step has no
 * count to show (the nav rail should render nothing in that case, not a
 * zero). Never keyed by index, and never special-cased by id in the view —
 * WizardNav renders whatever this returns.
 */
export function stepCount(id: WizardStepId, draft: WizardDraft): number | undefined {
  return STEP_COUNT[id]?.(draft);
}

/**
 * The steps whose completion is a HARD requirement — the only ones that block
 * forward navigation and the launch. Every other step may legitimately be
 * left unanswered (it just paints "incomplete" in the rail once visited).
 */
const REQUIRED_STEP_IDS: readonly WizardStepId[] = [
  "basics",
  "config",
  "location",
  "objective",
];

/** The step id at a zero-based index, or undefined when out of range. */
function stepIdAt(index: number): WizardStepId | undefined {
  return WIZARD_STEPS[index]?.id;
}

/** Whether the step identified by `id` has everything it asks for. */
export function isStepComplete(id: WizardStepId, draft: WizardDraft): boolean {
  return STEP_COMPLETE[id](draft);
}

/**
 * Required-field gate per wizard step: Basics (name + dates), Config (at least
 * one baseline website while baseline generation is on), Location (country),
 * Objective (min-length description + a category). Shared by the forward-nav
 * gate and the launch backstop so both enforce identical rules; every other
 * step has no required field and therefore never blocks.
 */
export function stepForwardBlocked(step: number, draft: WizardDraft): boolean {
  const id = stepIdAt(step);
  if (id === undefined || !REQUIRED_STEP_IDS.includes(id)) return false;
  return !isStepComplete(id, draft);
}

/**
 * Whether the footer's Continue control should be disabled for `step`.
 *
 * Blocked when either:
 *   - the step is a HARD requirement and unsatisfied (delegates to
 *     `stepForwardBlocked` — this branch is identical for every step, skippable
 *     or not, since a required step can never be bypassed by Continue either);
 *   - the step is optional (`skippable`) and its own completion predicate is
 *     unsatisfied — Continue must not silently skip an unanswered optional
 *     step; that is Skip's job (see WizardOverlay's unchanged `onSkip`, which
 *     still routes through `stepForwardBlocked` alone and therefore stays usable).
 *
 * Deliberately does NOT widen `stepForwardBlocked` itself — see that function's
 * doc comment for why (it also gates `firstIncompleteStep`, the launch backstop).
 */
export function continueBlocked(step: number, draft: WizardDraft): boolean {
  if (stepForwardBlocked(step, draft)) return true;
  const descriptor = WIZARD_STEPS[step];
  if (descriptor === undefined || !descriptor.skippable) return false;
  return !isStepComplete(descriptor.id, draft);
}

/**
 * The first wizard step (in launch order) whose required field is incomplete,
 * or -1 when all are satisfied. Drives the launch backstop's jump-to-the-first-
 * problem behavior — closing the loophole where the nav rail lets a user skip
 * the Location/Objective steps and reach Create.
 */
export function firstIncompleteStep(draft: WizardDraft): number {
  for (let index = 0; index < WIZARD_STEPS.length; index += 1) {
    if (stepForwardBlocked(index, draft)) return index;
  }
  return -1;
}

/** How the nav rail should paint a step. */
export type StepRailState = "active" | "done" | "incomplete" | "upcoming";

/**
 * The rail state for the step at `index`. "done" is completion-driven (not
 * merely visited), "incomplete" is the amber marker for a step the user opened
 * and left unanswered, and "upcoming" covers everything not yet reached.
 */
export function stepRailState(
  index: number,
  draft: WizardDraft,
  activeStep: number,
): StepRailState {
  if (index === activeStep) return "active";
  const id = stepIdAt(index);
  if (id === undefined) return "upcoming";
  // Never reached means "upcoming", whatever the draft happens to contain. The
  // rail may only report completion for a step the user actually opened —
  // otherwise the complete-on-visit steps (config, time, review), whose
  // predicates are unconditionally true, would paint "done" from first render,
  // which is the very thing this state machine exists to stop.
  if (!draft.visited.includes(index)) return "upcoming";
  return isStepComplete(id, draft) ? "done" : "incomplete";
}


--- frontends/range-mfe/src/wizard/types.ts (460 lines) ---
/**
 * Wizard draft model (epic #259 setup wizard).
 *
 * `WizardDraft` mirrors the prototype's mutable wizard data object
 * (docs/design source: /tmp/range-design/range/project/wizard.jsx). It is the
 * single source of truth the wizard reducer (useWizardDraft) persists to
 * localStorage and the launch hook (useCreateExerciseFromDraft) reads from.
 *
 * Step model — the location/objective convention:
 *   WIZARD_STEPS has 9 ordered nav entries. `location` and `objective` are TWO
 *   separate nav entries (so the nav rail + progress bar match the prototype's
 *   9-step count and each is independently jumpable) but they render the SAME
 *   component, StepLocationObjective, which switches on a `sub: "location" |
 *   "objective"` prop. The step registry (steps/index.ts) maps both indices to
 *   that one component with the appropriate `sub`. Keeping two nav entries (not
 *   one merged step) preserves the prototype's Review "Edit" jump targets
 *   (goto(2)=location, goto(3)=objective).
 */

import type { AttachContextDocumentRequest } from "../api/contextDocuments";
import type { FactionCandidate } from "../api/factions";
import {
  DISABLEABLE_PLATFORM_IDS,
  type DisableablePlatformId,
} from "../lib/platformVisibility";

/**
 * Hard ceiling on `WizardDraft.description`, shared by StepBasics (which
 * enforces it on the textarea via `maxLength` + the live counter) and by
 * `wizard/odinPrefill.ts` (which must respect the same ceiling because a
 * programmatic prefill is NOT capped by `maxLength` — that attribute only
 * constrains typing and pasting). Before this was shared, an ODIN prefill
 * landed a 669-character description in a 600-character field: the counter
 * read "669 / 600" the moment the step opened, and the instructor had to
 * delete text before they could type any.
 */
export const DESCRIPTION_MAX = 600;

/** A faction the user selected/authored in the Factions step. */
export interface WizardFactionDraft {
  readonly name: string;
  readonly description?: string;
  /** Hex from the curated palette (FactionColorPicker). */
  readonly color?: string;
  /** Headcount of synthetic profiles to generate for this faction (1–30, default 20). */
  readonly profileCount?: number;
  readonly allies?: string[];
  readonly adversaries?: string[];
  readonly influence?: number;
  readonly beliefs?: string[];
  readonly activityLevel?: string;
  readonly reasoning?: string;
  readonly confidence?: number;
  /**
   * How this faction entered the draft (Fix-Manual-Faction-Creation-2139):
   * `"manual"` for one the instructor typed in directly, `"discovered"` for
   * one accepted from AI faction discovery (`candidateToFactionDraft`).
   * Optional so pre-existing drafts (no storage-key bump) keep loading; a
   * stored draft without it is backfilled at read time in
   * `sanitizeFactions` from the presence of `reasoning`/`confidence`.
   */
  readonly origin?: "manual" | "discovered";
}

/** How the user chose to set the exercise up (Config step). */
export type WizardConfigMethod = "wizard" | "template" | "manual";

/**
 * Per-run outcome counts from the ODIN context-documents attach pass
 * (`useOdinContextDocuments`) — see `WizardDraft.odinContextDocsCounts`'s
 * doc comment for why these are persisted. Plain numbers only, so the
 * object round-trips through `JSON.stringify`/`parse` (localStorage
 * persistence) with no special handling.
 */
export interface OdinContextDocsCounts {
  readonly attached: number;
  readonly articlesTotal: number;
  readonly skipped: number;
  readonly failed: number;
}

/**
 * How timeline events get seeded (Timeline step). "" = not yet chosen, which is
 * also what "the operator skipped this step" looks like — skipping is a footer
 * action now, not a third mode, so there is deliberately no "skip" member
 * (issue #2118 redesign). There is also no "ai" member: that PickCard never
 * drove anything past a display string, so issue #2150 retired it rather than
 * finish building the never-implemented AI seeding path. The rail and Review
 * both read "" as Incomplete.
 */
export type WizardTimelineMode = "" | "manual";

/** The mutable wizard draft, persisted across sessions for resume (#461). */
export interface WizardDraft {
  // Basics
  name: string;
  description: string;
  startDate: string;
  endDate: string;
  timezone: string;
  generateBaseline: boolean;
  /**
   * Catalog website ids the instructor chose to enable for this exercise when
   * `generateBaseline` is on (epic #266, #889). Empty when the toggle is off;
   * the launch hook batch-enables exactly these on the new exercise.
   */
  baselineWebsiteIds: string[];
  /**
   * Whether outlet Characters auto-post their own baseline articles to the
   * feed (baseline-poll-self-heal follow-up). Only meaningful when
   * `generateBaseline` is on — no baseline websites means no outlet
   * Characters to post as. Defaults true: the launch hook maps this to
   * 'verbatim' | 'off' at create time so the instructor doesn't have to
   * hunt down the Setup tab toggle after the fact just to turn it ON.
   */
  baselineOutletPostingEnabled: boolean;
  /**
   * True once `baselineWebsiteIds` reflects a deliberate choice (the initial
   * default-select-all seed, or any subsequent user-driven mutation) rather
   * than the fresh-draft default. Gates the default-select-all effect in
   * `BaselineCatalogPicker` (StepConfig) to fire exactly once so a
   * deliberately-emptied selection is never re-seeded when the picker
   * unmounts/remounts (`generateBaseline` toggled off/on) or the step
   * re-renders. A resumed legacy draft (pre-fix) arrives with this false and
   * re-seeds once — matching prior behavior, no regression (#2126).
   */
  baselineWebsitesChosen: boolean;
  includeReddit: boolean;
  subreddits: string[];
  /**
   * Platform ids enabled for this exercise (platform-selection-in-wizard,
   * #2128). Mirrors the instructor's post-create Platforms card
   * (platformVisibility.ts) but chosen up front at creation time. Defaults to
   * every `DISABLEABLE_PLATFORM_IDS` entry (all on) on a fresh draft — an
   * exercise setting, not generated content, so it survives the Manual
   * "basics only" projection (see `basicsOnlyDraft`) and is deliberately NOT
   * counted by `isDraftMeaningful` (a platform toggle alone must not trigger
   * the resume/discard prompt).
   */
  enabledPlatforms: DisableablePlatformId[];
  // Config
  configMethod: WizardConfigMethod;
  // Location
  city: string;
  region: string;
  country: string;
  /**
   * ISO 3166-1 alpha-2 code for `country` (Location-Step, #wizard-location).
   * `""` when unset OR when a stored/typed `country` string could not be
