   * is always visited on open) and extended by setStep.
   */
  visited: number[];
  updatedAt: string;
}

/** A wizard nav step descriptor. */
export interface WizardStep {
  /** Stable id; also the registry/sub-step key. */
  readonly id:
    | "basics"
    | "config"
    | "location"
    | "objective"
    | "factions"
    | "analysis"
    | "timeline"
    | "context"
    | "review";
  /** i18n key suffix → m.range_wizard_step_<labelKey>_label(). */
  readonly labelKey:
    | "basics"
    | "config"
    | "location"
    | "objective"
    | "factions"
    | "analysis"
    | "timeline"
    | "context"
    | "review";
  /** Inline-SVG glyph id (see WizardNav). */
  readonly icon: string;
  /** Whether this step is AI-assisted (Sparkles marker in the nav). */
  readonly ai?: boolean;
  /**
   * Whether this step offers a footer Skip control that is semantically
   * distinct from Continue (i.e. Skip and Continue diverge in behavior, not
   * just in label). Absent/false means the step has exactly one forward
   * affordance.
   */
  readonly skippable?: boolean;
}

/**
 * The 9 ordered wizard steps. Matches data.jsx WIZARD_STEPS — note location +
 * objective are distinct entries (see the location/objective convention above).
 * `context` (the AI context-documents attach step) sits at index 7, immediately
 * before Review, so it never shifts the lower Review "Edit" jump targets
 * (goto 0/2/3/4/5/6).
 */
export const WIZARD_STEPS: readonly WizardStep[] = [
  { id: "basics", labelKey: "basics", icon: "info" },
  { id: "config", labelKey: "config", icon: "wand" },
  { id: "location", labelKey: "location", icon: "mapPin" },
  { id: "objective", labelKey: "objective", icon: "target" },
  // factions/analysis/timeline/context are the wizard's four OPTIONAL steps
  // (issue #2118 redesign): each carries `skippable` uniformly so the footer
  // shows exactly one enabled forward control at a time — Skip while
  // incomplete, Continue once the step's own completion predicate is
  // satisfied (see stepState.continueBlocked). This is NOT an AI escape
  // hatch for factions specifically; every optional step (including the
  // non-AI context step) gets the same treatment for consistency.
  { id: "factions", labelKey: "factions", icon: "users", ai: true, skippable: true },
  { id: "analysis", labelKey: "analysis", icon: "barChart", ai: true, skippable: true },
  { id: "timeline", labelKey: "timeline", icon: "calendar", skippable: true },
  { id: "context", labelKey: "context", icon: "fileText", skippable: true },
  { id: "review", labelKey: "review", icon: "check" },
];

/**
 * Project a draft down to the Basics step's own fields (name, description,
 * dates, timezone) on top of a fresh draft.
 *
 * Manual configuration creates the exercise "from just the basics you've
 * entered here" and skips every guided step, so anything the user did in the
 * wizard before switching to manual — baseline outlets, subreddits, drafted
 * factions, location, objective, the PMESII analysis, context documents,
 * timeline mode — must NOT reach the backend. Without this projection the
 * launch hook still fires the post-create side effects (BatchEnableWebsites,
 * CreateFaction, attach) for that abandoned state.
 *
 * `configMethod` is preserved so the launched draft still reports how it was
 * created. Resume bookkeeping (step/visited/updatedAt) is irrelevant to launch
 * and is left at its fresh-draft value.
 */
export function basicsOnlyDraft(draft: WizardDraft): WizardDraft {
  return {
    ...createEmptyDraft(),
    name: draft.name,
    description: draft.description,
    startDate: draft.startDate,
    endDate: draft.endDate,
    timezone: draft.timezone,
    configMethod: draft.configMethod,
    enabledPlatforms: draft.enabledPlatforms,
  };
}

/**
 * Resolve the instructor's own browser timezone (IANA name), guarded against
 * a runtime where `Intl.DateTimeFormat` throws or resolves an empty zone
 * (e.g. an older or jsdom-like environment) by falling back to "UTC".
 *
 * StepTime was the only wizard UI that ever wrote `draft.timezone`; now that
 * it's gone, this is the sole source of a wizard-created exercise's
 * timezone, so it must reflect the instructor's locale rather than a
 * hardcoded default. Resolved once at module load; a browser's zone does not
 * change mid-session.
 */
export function resolveDefaultTimezone(): string {
  try {
    const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return timeZone && timeZone.length > 0 ? timeZone : "UTC";
  } catch {
    return "UTC";
  }
}

/** Default IANA timezone for a fresh draft. */
const DEFAULT_TIMEZONE = resolveDefaultTimezone();

/** Build a fresh, empty wizard draft (the wizard's initial state). */
export function createEmptyDraft(): WizardDraft {
  return {
    name: "",
    description: "",
    startDate: "",
    endDate: "",
    timezone: DEFAULT_TIMEZONE,
    generateBaseline: false,
    baselineWebsiteIds: [],
    baselineOutletPostingEnabled: true,
    baselineWebsitesChosen: false,
    includeReddit: false,
    subreddits: [],
    enabledPlatforms: [...DISABLEABLE_PLATFORM_IDS],
    configMethod: "wizard",
    city: "",
    region: "",
    country: "",
    countryCode: "",
    regionCode: null,
    objectiveCategory: "General",
    objective: "",
    factions: [],
    contextDocuments: [],
    analysisDone: false,
    timelineMode: "",
    templateId: null,
    templateName: null,
    templateSource: null,
    odinPrefill: false,
    odinContextDocsTemplateId: null,
    odinContextDocsCounts: null,
    step: 0,
    visited: [0],
    updatedAt: new Date(0).toISOString(),
  };
}


