/**
 * useCreateExerciseFromDraft — turns a completed WizardDraft into a real
 * exercise, left in its default (planning) status.
 *
 * Orchestration (Facade over the exercises + factions BFF clients):
 *   1. createExercise({ name, description, start_date, end_date, timezone })
 *   2. best-effort createFaction(id, …) for every draft faction SEQUENTIALLY —
 *      each faction's createFaction + generateCharacters fully resolve before
 *      the next faction starts. Both calls kick off LLM-backed work server-side
 *      (createFaction triggers a faction-embed job; generateCharacters a
 *      persona-generation job), so firing every faction at once bursts ~2N
 *      concurrent LLM calls and trips the LiteLLM router cooldown — serializing
 *      spreads that load out over the launch. A single faction failure is
 *      collected into `warnings[]` and never aborts the launch (the exercise
 *      already exists).
 *
 * Returns { exerciseId, warnings }. The caller navigates to the new overview
 * and may surface warnings non-fatally.
 */

import { useCallback } from "react";
import {
  createExercise,
  type CreateExerciseRequest,
} from "../api/exercises";
import {
  createFaction,
  generateCharacters,
  updateFaction,
  type FactionActivity,
} from "../api/factions";
import { batchEnableWebsites } from "../api/baseline";
import { attachContextDocument } from "../api/contextDocuments";
import { toTimestampOrNull } from "../components/exerciseForm";
import { PROFILE_COUNT_DEFAULT } from "../constants/factionProfileCount";
import {
  DISABLEABLE_PLATFORM_IDS,
  type DisableablePlatformId,
} from "../lib/platformVisibility";
import type { WizardDraft } from "./types";

export interface LaunchResult {
  readonly exerciseId: string;
  /** Names of factions that failed to create (launch still succeeded). */
  readonly warnings: string[];
}

export interface UseCreateExerciseFromDraft {
  readonly launch: (draft: WizardDraft) => Promise<LaunchResult>;
}

/**
 * Stable marker pushed into `warnings` when the post-create BatchEnable fails.
 * Like the faction-name markers, this is a non-display identifier — the caller
 * maps warnings to localized copy when it surfaces them.
 */
const BASELINE_WARNING = "baseline";

/**
 * Stable marker pushed into `warnings` when a post-create context-document
 * attach fails. Like the faction/baseline markers, it is a non-display id — the
 * caller maps warnings to localized copy. Suffixed with the document name so
 * multiple failures stay distinct.
 */
const CONTEXT_DOC_WARNING = "context_document";

/** Empty strings become undefined so the BFF/proto omits the optional field. */
function orUndefined(value: string): string | undefined {
  return value.trim() === "" ? undefined : value;
}

/**
 * Compose the Location step's town/region/country into the single
 * `location_label` the exercise stores (and the overview renders) — e.g.
 * "Seattle, WA, United States". Empty when none were entered.
 */
function composeLocation(draft: WizardDraft): string | undefined {
  return orUndefined(
    [draft.city, draft.region, draft.country].filter(Boolean).join(", "),
  );
}

/**
 * Derive the create-time platform DENYLIST from the wizard's allowlist-shaped
 * draft field (`enabledPlatforms`). The stored document only ever records
 * disabled platforms — absent key = enabled — so every enabled id is simply
 * left out, never written as `true`. When nothing was deselected, returns
 * `undefined` so the request omits the key entirely, matching the server's
 * own canonicalization of an all-enabled document (mirrors the
 * `baseline_outlet_post_mode` omit-when-default shape above).
 */
function toPlatformVisibility(
  draft: WizardDraft,
): Partial<Record<DisableablePlatformId, false>> | undefined {
  const enabled = new Set(draft.enabledPlatforms);
  const denylist: Partial<Record<DisableablePlatformId, false>> = {};
  for (const id of DISABLEABLE_PLATFORM_IDS) {
    if (!enabled.has(id)) denylist[id] = false;
  }
  return Object.keys(denylist).length > 0 ? denylist : undefined;
}

function toCreateRequest(draft: WizardDraft): CreateExerciseRequest {
  return {
    name: draft.name.trim(),
    description: orUndefined(draft.description),
    location_label: composeLocation(draft),
    start_date: toTimestampOrNull(draft.startDate),
    end_date: toTimestampOrNull(draft.endDate),
    timezone: draft.timezone,
    // Link the pre-create PMESII analysis (#479). undefined is dropped by
    // JSON.stringify, so a skipped analysis sends no key at all.
    analysis_draft_id: draft.analysisDraftId,
    // Link the pre-create Factions-step AI discovery draft (the "no
    // discovery for this draft" 404 fix). This is an INDEPENDENT client
    // UUID from analysisDraftId — the wizard mints a separate handle per
    // step — so it is forwarded on its own key, never derived from
    // analysisDraftId. undefined is dropped by JSON.stringify, so a
    // Factions step that never ran AI discovery sends no key at all.
    faction_discovery_draft_id: draft.factionDiscoveryDraftId,
    // Wizard platform-selection step (#2128): a pure denylist, omitted
    // entirely when every platform is enabled. See toPlatformVisibility.
    platform_visibility: toPlatformVisibility(draft),
    // baseline-poll-self-heal follow-up: only meaningful when baseline
    // content is actually enabled — no baseline websites means no outlet
    // Characters to post as, so sending a mode either way is moot. Omitted
    // (undefined) when generateBaseline is off, so the server default
    // ('verbatim') applies uniformly rather than this call site inventing
    // its own "off" for a case the toggle was never shown for.
    baseline_outlet_post_mode: draft.generateBaseline
      ? draft.baselineOutletPostingEnabled
        ? "verbatim"
        : "off"
      : undefined,
  };
}

export function useCreateExerciseFromDraft(): UseCreateExerciseFromDraft {
  const launch = useCallback(
    async (draft: WizardDraft): Promise<LaunchResult> => {
      const exercise = await createExercise(toCreateRequest(draft));

      const warnings: string[] = [];

      // Phase 0: attach the context documents collected in the wizard. There
      // was no exercise_id at collection time, so the references are attached
      // now that the exercise exists. Best-effort, mirroring the faction /
      // baseline policy: the exercise already exists, so an attach failure
      // must NEVER abort the launch — each is recorded as a non-fatal warning
      // the caller can surface. Sequential to keep the request load gentle
      // (this is a cheap metadata write, but consistency wins).
      for (const doc of draft.contextDocuments) {
        try {
          await attachContextDocument(exercise.id, doc);
        } catch {
          warnings.push(`${CONTEXT_DOC_WARNING}:${doc.document_name}`);
        }
      }

      // Phase 1: create each faction and build a name→id map for relationship
      // wiring. Run SEQUENTIALLY — both createFaction (faction-embed) and
      // generateCharacters (persona-generation) enqueue LLM-backed jobs, so a
      // parallel fan-out would burst ~2N concurrent calls and trip the LiteLLM
      // router cooldown. Awaiting each faction before the next spreads the load.
      const nameToId = new Map<string, string>();
      for (const faction of draft.factions) {
        try {
          const created = await createFaction(exercise.id, {
            name: faction.name,
            description: orUndefined(faction.description ?? ""),
            profile_count: faction.profileCount ?? PROFILE_COUNT_DEFAULT,
            color: faction.color,
            ...(faction.influence !== undefined
              ? { influence: faction.influence }
              : {}),
            ...(faction.beliefs !== undefined && faction.beliefs.length > 0
              ? { stance_keywords: faction.beliefs }
              : {}),
            ...(faction.activityLevel !== undefined
              ? { activity_level: faction.activityLevel as FactionActivity }
              : {}),
          });
          nameToId.set(faction.name, created.id);
          // Best-effort: kick off background character generation. A failure
          // here is recorded as a warning but never aborts the launch.
          try {
            await generateCharacters(
              exercise.id,
              created.id,
              faction.profileCount ?? PROFILE_COUNT_DEFAULT,
            );
          } catch {
            warnings.push(`generate:${faction.name}`);
          }
        } catch {
          // A faction failure is non-fatal — the exercise already exists.
          warnings.push(faction.name);
        }
      }

      // Phase 2: wire ally/adversary relationships now that all faction IDs are known.
      await Promise.all(
        draft.factions.map(async (faction) => {
          const factionId = nameToId.get(faction.name);
          if (factionId === undefined) return; // creation failed, skip
          const hasAllies = (faction.allies?.length ?? 0) > 0;
          const hasAdversaries = (faction.adversaries?.length ?? 0) > 0;
          if (!hasAllies && !hasAdversaries) return; // nothing to wire

          const resolvedAllies = (faction.allies ?? [])
            .map((name) => nameToId.get(name))
            .filter((id): id is string => id !== undefined);
          const resolvedAdversaries = (faction.adversaries ?? [])
            .map((name) => nameToId.get(name))
            .filter((id): id is string => id !== undefined);

          // Only PATCH when there are resolvable relationships.
          if (resolvedAllies.length === 0 && resolvedAdversaries.length === 0)
            return;

          try {
            await updateFaction(exercise.id, factionId, {
              ...(hasAllies ? { allies: resolvedAllies } : {}),
              ...(hasAdversaries ? { adversaries: resolvedAdversaries } : {}),
            });
          } catch {
            // Relationship wiring failure is non-fatal — the faction already exists.
          }
        }),
      );

      // Enable the chosen baseline catalog websites on the new exercise (#889).
      // Best-effort, mirroring the faction policy: the exercise already
      // exists, so a BatchEnable failure must NOT abort the launch — it is
      // recorded as a non-fatal warning the caller can surface.
      if (draft.generateBaseline && draft.baselineWebsiteIds.length > 0) {
        try {
          await batchEnableWebsites(exercise.id, draft.baselineWebsiteIds);
        } catch {
          warnings.push(BASELINE_WARNING);
        }
      }

      return { exerciseId: exercise.id, warnings };
    },
    [],
  );

  return { launch };
}


