// Does the wizard draft hold user-entered content worth preserving? (#1439)
import { createEmptyDraft, type WizardDraft } from "./types";

// Bookkeeping fields (step, updatedAt) are ignored — they move even on a
// pristine draft. Drives WizardOverlay's discard guard. (timezone is not
// checked either: since StepTime was removed, nothing in the wizard writes
// draft.timezone away from its resolved-browser default, so a "timezone
// changed" case can no longer occur here.)
export function isDraftMeaningful(draft: WizardDraft): boolean {
  const empty = createEmptyDraft();

  // Free-text fields — meaningful if non-empty after trim.
  if (draft.name.trim() !== "") return true;
  if (draft.description.trim() !== "") return true;
  if (draft.objective.trim() !== "") return true;

  // Date strings — meaningful if set.
  if (draft.startDate !== "") return true;
  if (draft.endDate !== "") return true;

  // Location fields — meaningful if set.
  if (draft.city !== "") return true;
  if (draft.region !== "") return true;
  if (draft.country !== "") return true;

  // Objective category — meaningful if changed from the default.
  if (draft.objectiveCategory !== empty.objectiveCategory) return true;

  // Arrays — meaningful if non-empty.
  if (draft.factions.length > 0) return true;
  if (draft.baselineWebsiteIds.length > 0) return true;
  if (draft.subreddits.length > 0) return true;

  // Boolean flags — meaningful if toggled on.
  if (draft.generateBaseline) return true;
  if (draft.includeReddit) return true;
  if (draft.analysisDone) return true;
  // A deliberate choice was made over the baseline site selection (including
  // deliberately clearing it to empty), even if generateBaseline was since
  // toggled back off — that choice is still user-entered state worth
  // preserving across the discard guard (#2126).
  if (draft.baselineWebsitesChosen) return true;

  // Enum fields — meaningful if changed from defaults.
  if (draft.configMethod !== empty.configMethod) return true;
  if (draft.timelineMode !== empty.timelineMode) return true;

  // Template intent — meaningful if a template was chosen.
  if (draft.templateId !== null) return true;

  // analysisDraftId persists on Run, before analysisDone flips — catches a
  // still-computing/errored PMESII run so it is not silently discarded.
  if (draft.analysisDraftId) return true;

  // Visited — meaningful if the user has progressed past step 0.
  if (draft.visited.length > 1) return true;

  return false;
}


