/**
 * factionCandidate — shared `FactionCandidate` -> `WizardFactionDraft`
 * mapping (#1724 Task 11).
 *
 * Lifted out of `StepFactions.tsx` (previously a private, unexported
 * `candidateToFactionDraft`) so the manual AI-discovery accept path
 * (StepFactions) and the ODIN-grounded generation completion path
 * (ExerciseSetupWizardRoute) can never drift apart on the `origin` backfill
 * or the `reasoning`/`confidence` carry-through that `sanitizeFactions`
 * (`useWizardDraft.ts`) relies on to classify a faction as "discovered"
 * rather than "manual" on read. Both call sites must produce byte-identical
 * `WizardFactionDraft` shapes for the same `FactionCandidate` input.
 */

import type { FactionCandidate } from "../api/factions";
import type { WizardFactionDraft } from "./types";

/** Convert an accepted AI candidate to the persisted WizardFactionDraft shape. */
export function candidateToFactionDraft(c: FactionCandidate): WizardFactionDraft {
  return {
    name: c.name,
    color: c.color || undefined,
    description: c.description || undefined,
    beliefs: [...c.stance_keywords],
    influence: c.influence,
    activityLevel: c.activity_level,
    profileCount: c.profile_count,
    allies: [...c.allies],
    adversaries: [...c.adversaries],
    reasoning: c.reasoning,
    confidence: c.confidence,
    origin: "discovered",
  };
}


