/**
 * Shared ODIN scalar-prefill logic (#1724 exercise: "Use this environment"
 * bug fix). Lifted out of `ExerciseSetupWizardRoute.tsx` (where it was
 * defined and used solely by the "Generate & Apply" completion patch) so BOTH
 * ODIN entry paths — "Use this environment" (`onSelectTemplate`) and
 * "Generate & Apply" (`applyGenerationResult`) — build their scalar half from
 * the exact same code and cannot drift.
 *
 * Product decision (live design review, #1724 exercise): "Use this
 * environment" must prefill the setting WITHOUT running the AI — i.e. apply
 * everything Generate & Apply writes EXCEPT the AI-generated factions and the
 * environment analysis. `odinScenarioPatch` below is that shared "everything
 * except factions/analysis" half.
 */

import type { OdinTemplateDetail } from "../api/odin";
import { codeFromName } from "../lib/countries";
import type { WizardDraftPatch } from "./useWizardDraft";
import { DESCRIPTION_MAX } from "./types";

/** English-key-suffix objective category fallback (mirrors the wizard's own
 * `OBJECTIVE_CATEGORIES` convention in StepLocationObjective.tsx — the
 * PERSISTED value is always one of those locale-stable English strings, never
 * a raw backend token). Matches the semantic category range-svc's own
 * grounding fallback derives (`information_operations`) for an OE the
 * instructor hasn't supplied an objective for. */
const ODIN_GENERATE_FALLBACK_OBJECTIVE_CATEGORY = "Information operations";

/**
 * Collapse every whitespace run to a single space. ODIN's scraped infobox
 * values carry the source table's own column padding ("Donovians   80%",
 * "Kalmyk    Karachay-Balkar") and embedded newlines; pasted verbatim into a
 * prose sentence those read as broken text.
 */
function normalizeWhitespace(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

/**
 * Truncate to `max` characters on a word boundary, appending an ellipsis
 * only when something was actually dropped. `DESCRIPTION_MAX` is the field's
 * own ceiling (see its doc in ./types) and `maxLength` does not apply to a
 * programmatic prefill, so this function is what keeps the two in agreement.
 */
function truncateToWord(value: string, max: number): string {
  if (value.length <= max) return value;
  const hard = value.slice(0, max - 1);
  const lastSpace = hard.lastIndexOf(" ");
  // A single unbroken token longer than the field takes the hard cut.
  const body = lastSpace > 0 ? hard.slice(0, lastSpace) : hard;
  return `${body.replace(/[\s,;:.\u2014-]+$/, "")}\u2026`;
}

/**
 * Derive the wizard-prefill scalars (#1724 Task 11 binding requirement 3)
 * from the ALREADY-FETCHED ODIN template detail — the same read path the
 * preview drawer itself uses (`useOdinTemplateDetail`), so no new prefill
 * plumbing is introduced. Mirrors range-svc's own grounding-fallback
 * derivation of the OE title/official name and capital closely enough that
 * what the wizard shows the instructor matches what actually grounded the
 * run, without either side importing the other's code.
 *
 * `description` is the deliberate exception to that mirroring — see the
 * comment on its own derivation below. range-svc's `_derive_description`
 * builds LLM grounding material; this one builds a briefing line a person
 * reads inside a 600-character textarea.
 */
export function buildOdinScenarioFields(detail: OdinTemplateDetail): {
  readonly name: string;
  readonly description: string;
  readonly country: string;
  readonly city: string;
  readonly objective: string;
  readonly objectiveCategory: string;
} {
  const name = detail.card.name;
  const country = detail.official_name !== "" ? detail.official_name : name;
  const city = detail.capital;
  const objective =
    country !== ""
      ? `Understand and shape the information environment in ${country}.`
      : "Understand and shape the information environment.";
  // A one-sentence briefing summary, NOT a fact dump. The field's own
  // placeholder promises "a 1-2 sentence summary participants will see in the
  // briefing", and this used to emit a clause-per-fact render of all five
  // infobox facts instead — for Donovia that is 669 characters of
  // "Government: ... Population: ... Official languages: <25 entries>. Major
  // ethnic groups: <12 entries>", over a 600-character field, padded with the
  // source table's own column whitespace.
  //
  // So only the three SHORT scalars ride this sentence. The two enumerations
  // (`official_languages`, `ethnic_groups`) are dropped deliberately, not
  // forgotten: they are already on the preview drawer's own fact grid and in
  // the ODIN article context documents `useOdinContextDocuments` attaches, and
  // neither belongs in a participant-facing briefing line.
  //
  // This is the one place that deliberately DIVERGES from range-svc's
  // `_derive_description` (workers/generation/odin_exercise/grounding.py),
  // which the rest of this module mirrors. That function's output is LLM
  // grounding material, where exhaustive facts genuinely help; this string is
  // read by a person in a capped textarea. Same source facts, different
  // consumer, so do not "re-sync" the two.
  const summaryFacts: string[] = [];
  if (detail.government !== "") {
    summaryFacts.push(normalizeWhitespace(detail.government));
  }
  if (detail.population !== "") {
    summaryFacts.push(`population ${normalizeWhitespace(detail.population)}`);
  }
  if (city !== "") summaryFacts.push(`capital ${normalizeWhitespace(city)}`);
  const head = `${normalizeWhitespace(name)} operational environment`;
  const description = truncateToWord(
    summaryFacts.length > 0
      ? `${head} \u2014 ${summaryFacts.join(", ")}.`
      : `${head}.`,
    DESCRIPTION_MAX,
  );
  return {
    name,
    description,
    country,
    city,
    objective,
    objectiveCategory: ODIN_GENERATE_FALLBACK_OBJECTIVE_CATEGORY,
  };
}

/**
 * The shared scalar half of BOTH ODIN prefill paths ("Use this environment"
 * and "Generate & Apply", #1724 exercise). Sets everything Generate & Apply
 * writes to the draft EXCEPT the AI-generated `factions` and the environment
 * `analysisDone`/draft-id bookkeeping — those stay Generate & Apply's own
 * job, applied only alongside this patch, never by it.
 *
 * `region`/`regionCode` are deliberately blanked, never carried from ODIN's
 * own `region` (a combatant-command band — `africa`, `indo_pacific`, … — not
 * a sub-national region): writing it would make `isRegionProvablyInvalid`
 * true, blocking the Location step's forward-nav and the launch backstop.
 *
 * `countryCode` legitimately resolves to `""` for a fictional DATE
 * environment (Olvana, Atropia, Donovia) that `codeFromName` cannot match —
 * that is expected and harmless, since `isCountryMissing` only checks that
 * `country` itself is non-empty.
 *
 * Sets `odinPrefill: true` in this SAME patch — the two ODIN paths are the
 * only writers of that field, and only when these scalars actually landed.
 */
export function odinScenarioPatch(
  detail: OdinTemplateDetail,
  templateId: string,
  templateName: string,
): WizardDraftPatch {
  const scenario = buildOdinScenarioFields(detail);
  return {
    name: scenario.name,
    description: scenario.description,
    country: scenario.country,
    city: scenario.city,
    countryCode: codeFromName(scenario.country) ?? "",
    region: "",
    regionCode: null,
    objective: scenario.objective,
    objectiveCategory: scenario.objectiveCategory,
    templateId,
    templateName,
    templateSource: "odin",
    configMethod: "template",
    odinPrefill: true,
  };
}


