/**
 * Wizard draft model (epic #259 setup wizard).
 *
 * `WizardDraft` mirrors the prototype's mutable wizard data object
 * (docs/design source: /tmp/range-design/range/project/wizard.jsx). It is the
 * single source of truth the wizard reducer (useWizardDraft) persists to
 * localStorage and the launch hook (useCreateExerciseFromDraft) reads from.
 *
 * Step model — the location/objective convention:
 *   WIZARD_STEPS has 9 ordered nav entries. `location` and `objective` are TWO
 *   separate nav entries (so the nav rail + progress bar match the prototype's
 *   9-step count and each is independently jumpable) but they render the SAME
 *   component, StepLocationObjective, which switches on a `sub: "location" |
 *   "objective"` prop. The step registry (steps/index.ts) maps both indices to
 *   that one component with the appropriate `sub`. Keeping two nav entries (not
 *   one merged step) preserves the prototype's Review "Edit" jump targets
 *   (goto(2)=location, goto(3)=objective).
 */

import type { AttachContextDocumentRequest } from "../api/contextDocuments";
import type { FactionCandidate } from "../api/factions";
import {
  DISABLEABLE_PLATFORM_IDS,
  type DisableablePlatformId,
} from "../lib/platformVisibility";

/**
 * Hard ceiling on `WizardDraft.description`, shared by StepBasics (which
 * enforces it on the textarea via `maxLength` + the live counter) and by
 * `wizard/odinPrefill.ts` (which must respect the same ceiling because a
 * programmatic prefill is NOT capped by `maxLength` — that attribute only
 * constrains typing and pasting). Before this was shared, an ODIN prefill
 * landed a 669-character description in a 600-character field: the counter
 * read "669 / 600" the moment the step opened, and the instructor had to
 * delete text before they could type any.
 */
export const DESCRIPTION_MAX = 600;

/** A faction the user selected/authored in the Factions step. */
export interface WizardFactionDraft {
  readonly name: string;
  readonly description?: string;
  /** Hex from the curated palette (FactionColorPicker). */
  readonly color?: string;
  /** Headcount of synthetic profiles to generate for this faction (1–30, default 20). */
  readonly profileCount?: number;
  readonly allies?: string[];
  readonly adversaries?: string[];
  readonly influence?: number;
  readonly beliefs?: string[];
  readonly activityLevel?: string;
  readonly reasoning?: string;
  readonly confidence?: number;
  /**
   * How this faction entered the draft (Fix-Manual-Faction-Creation-2139):
   * `"manual"` for one the instructor typed in directly, `"discovered"` for
   * one accepted from AI faction discovery (`candidateToFactionDraft`).
   * Optional so pre-existing drafts (no storage-key bump) keep loading; a
   * stored draft without it is backfilled at read time in
   * `sanitizeFactions` from the presence of `reasoning`/`confidence`.
   */
  readonly origin?: "manual" | "discovered";
}

/** How the user chose to set the exercise up (Config step). */
export type WizardConfigMethod = "wizard" | "template" | "manual";

/**
 * Per-run outcome counts from the ODIN context-documents attach pass
 * (`useOdinContextDocuments`) — see `WizardDraft.odinContextDocsCounts`'s
 * doc comment for why these are persisted. Plain numbers only, so the
 * object round-trips through `JSON.stringify`/`parse` (localStorage
 * persistence) with no special handling.
 */
export interface OdinContextDocsCounts {
  readonly attached: number;
  readonly articlesTotal: number;
  readonly skipped: number;
  readonly failed: number;
}

/**
 * How timeline events get seeded (Timeline step). "" = not yet chosen, which is
 * also what "the operator skipped this step" looks like — skipping is a footer
 * action now, not a third mode, so there is deliberately no "skip" member
 * (issue #2118 redesign). There is also no "ai" member: that PickCard never
 * drove anything past a display string, so issue #2150 retired it rather than
 * finish building the never-implemented AI seeding path. The rail and Review
 * both read "" as Incomplete.
 */
export type WizardTimelineMode = "" | "manual";

/** The mutable wizard draft, persisted across sessions for resume (#461). */
export interface WizardDraft {
  // Basics
  name: string;
  description: string;
  startDate: string;
  endDate: string;
  timezone: string;
  generateBaseline: boolean;
  /**
   * Catalog website ids the instructor chose to enable for this exercise when
