  baselineWebsitesChosen: boolean;
  includeReddit: boolean;
  subreddits: string[];
  /**
   * Platform ids enabled for this exercise (platform-selection-in-wizard,
   * #2128). Mirrors the instructor's post-create Platforms card
   * (platformVisibility.ts) but chosen up front at creation time. Defaults to
   * every `DISABLEABLE_PLATFORM_IDS` entry (all on) on a fresh draft — an
   * exercise setting, not generated content, so it survives the Manual
