/**
 * useWizardDraft — module-level wizard state with localStorage persistence.
 *
 * Modeled on files-mfe/src/state/useViewMode.ts: a single module-level store
 * + useSyncExternalStore so every wizard surface (overlay, nav, steps, the
 * resume banner on the list page) observes the same draft, and so the
 * resume-banner check on the list page sees writes made by the overlay.
 * localStorage access is wrapped in try/catch for SSR / disabled-storage
 * safety. The whole {step,data} object is the persisted unit (key
 * `range:wizard-draft:v2`); we persist on every change and clear on reset.
 *
 * v2 (#2136): bumped from v1 when the "Time" step was removed from the
 * wizard registry, shifting every later step's index down by one. A v1
 * draft's persisted `step` would resolve to the wrong step under the new
 * registry, so the key bump orphans old drafts instead of silently
 * resuming one step off.
 */

import { useCallback, useSyncExternalStore } from "react";
import { codeFromName, COUNTRY_CODES } from "../lib/countries";
import { resolveRegionCodeFromText } from "../lib/locationMatch";
import {
  DISABLEABLE_PLATFORM_IDS,
  type DisableablePlatformId,
} from "../lib/platformVisibility";
import type { FactionCandidate } from "../api/factions";
import {
  createEmptyDraft,
  type WizardDraft,
  type WizardFactionDraft,
  type WizardTimelineMode,
} from "./types";

const STORAGE_KEY = "range:wizard-draft:v2";
const ORPHANED_V1_STORAGE_KEY = "range:wizard-draft:v1";

const DISABLEABLE_PLATFORM_ID_SET: ReadonlySet<string> = new Set(
  DISABLEABLE_PLATFORM_IDS,
);

const KNOWN_COUNTRY_CODE_SET: ReadonlySet<string> = new Set(COUNTRY_CODES);

/**
 * Resolve a persisted `countryCode`/`country` pair to a known ISO code.
 *
 * - A present, known `countryCode` is uppercased and kept as-is.
 * - An absent/unknown `countryCode` with a `country` display name is
 *   back-derived via `codeFromName()` — the folded, non-throwing reverse
 *   lookup. `Intl.DisplayNames#of()` THROWS on a display-name input (e.g.
 *   `of("United States")`), so a stored draft value must never reach it;
 *   `codeFromName()` is the only safe path here.
 * - Unresolvable (no match, e.g. a legacy free-text value like "Atlantis")
 *   → `""`, deliberately NOT clearing `country`. The combobox surfaces this
 *   as an unconfirmed state prompting the user to confirm, rather than
 *   silently blanking a required field that gates forward-nav.
 */
function resolveCountryCode(
  rawCountryCode: unknown,
  country: string,
): string {
  if (
    typeof rawCountryCode === "string" &&
    KNOWN_COUNTRY_CODE_SET.has(rawCountryCode.toUpperCase())
  ) {
    return rawCountryCode.toUpperCase();
  }
  if (country === "") return "";
  return codeFromName(country) ?? "";
}

/**
 * Exhaustive keying off `WizardTimelineMode` so the valid set is derived from
 * the type, not a drifting literal list: dropping a member (as #2118 dropped
 * "skip") or adding one fails to typecheck here until this map is updated.
 */
const WIZARD_TIMELINE_MODE_FLAGS: Readonly<Record<WizardTimelineMode, true>> = {
  "": true,
  manual: true,
};

const WIZARD_TIMELINE_MODE_SET: ReadonlySet<string> = new Set(
  Object.keys(WIZARD_TIMELINE_MODE_FLAGS),
);

/**
 * Intersect a persisted `enabledPlatforms` value with the current
 * `DISABLEABLE_PLATFORM_IDS`, so a stale draft carrying pre-rebrand ids (`x`,
 * `reddit`, `facebook`, `telegram`, `video`, `youtube`) or any other unknown
 * id loads with those stripped.
 *
 * `null` means "no usable selection was persisted" and tells the caller to fall
 * back to the all-on default. That covers a missing/non-array value AND a
 * NON-EMPTY array in which nothing survived the filter — a stale all-legacy
 * draft like `["twitter","reddit"]` must resume all-on, never all-off (an
 * all-off resume would launch a denylist disabling every platform).
 *
 * A persisted EMPTY array is different: the user deliberately switched
 * everything off, so it is returned as `[]` and honored. Telling the two apart
 * needs the raw input length, not just the filtered result.
 */
export function sanitizeEnabledPlatforms(
  raw: unknown,
): DisableablePlatformId[] | null {
  if (!Array.isArray(raw)) return null;
  const kept = raw.filter((id): id is DisableablePlatformId =>
    DISABLEABLE_PLATFORM_ID_SET.has(id),
  );
  if (kept.length === 0 && raw.length > 0) return null;
  return kept;
}

/**
 * Coerce a persisted `timelineMode` to a member of `WizardTimelineMode`.
 *
 * A draft persisted before the #2118 redesign can carry the retired
 * `"skip"` mode, or before the #2150 redesign can carry the retired `"ai"`
 * mode (its PickCard never drove anything past a display string), or any
 * other unknown value. Left alone any of these is truthy, so the Timeline
 * step reads as complete — the rail paints it Completed, Continue unlocks,
 * and Review would mislabel it as the manual editor. `""` ("not yet chosen")
 * is the only safe resume value.
 */
export function sanitizeTimelineMode(raw: unknown): WizardTimelineMode {
  return isWizardTimelineMode(raw) ? raw : "";
}

function isWizardTimelineMode(raw: unknown): raw is WizardTimelineMode {
  return typeof raw === "string" && WIZARD_TIMELINE_MODE_SET.has(raw);
}

/**
 * Normalize a persisted `factions` value (Factions step, epic #259):
 *
 * - A non-array (missing, legacy scalar, corrupt payload) becomes `[]`.
 * - An entry with no `name`, or a blank/whitespace-only one, is dropped
 *   outright — it can never be selected, rendered, or referenced by another
 *   faction's allies/adversaries, so keeping it around is pure noise.
 * - Each surviving entry's `allies`/`adversaries` are filtered down to names
 *   that are themselves present in the sanitized (post-drop) list, and a
 *   self-reference (a faction listing its own name) is stripped — both cases
 *   arise from a faction having been renamed/removed by an older client
 *   build, or hand-edited storage, without this normalizer in place.
 * - `origin` is backfilled when absent or not a valid `"manual" |
 *   "discovered"` literal: `reasoning`/`confidence` are populated ONLY by
 *   `candidateToFactionDraft` (the AI-discovery path), so their presence is
 *   an exact signal for "discovered" on every draft a predecessor of this
 *   normalizer could have written. A stored, valid literal is trusted as-is
 *   (explicit wins over the heuristic, even for a hand-edited edge case like
 *   a "manual" faction that also carries `reasoning`).
 *
 * Read-time only, like every other normalizer in this file: the result is
 * never written back to storage (see the module doc and types.ts:108-119).
 */
function isValidFactionOrigin(raw: unknown): raw is "manual" | "discovered" {
  return raw === "manual" || raw === "discovered";
}

export function sanitizeFactions(raw: unknown): WizardFactionDraft[] {
  if (!Array.isArray(raw)) return [];
  const named = raw.filter(
    (f): f is WizardFactionDraft =>
      typeof f === "object" &&
      f !== null &&
      typeof (f as { name?: unknown }).name === "string" &&
      (f as { name: string }).name.trim() !== "",
  );
  const validNames = new Set(named.map((f) => f.name));
  return named.map((f) => ({
    ...f,
    origin: isValidFactionOrigin(f.origin)
      ? f.origin
      : f.reasoning !== undefined || f.confidence !== undefined
        ? "discovered"
        : "manual",
    allies: f.allies?.filter((a) => a !== f.name && validNames.has(a)),
    adversaries: f.adversaries?.filter((a) => a !== f.name && validNames.has(a)),
  }));
}

/**
 * Sanitize `factionSuggestions`: array guard, drop any entry with an
 * empty/non-string `name`. Mirrors `sanitizeFactions`' name filter above but
 * skips the allies/adversaries reference reconciliation and `origin`
 * backfill — a `FactionCandidate` (server discovery shape) carries neither.
 * Read-time only, like every other normalizer in this file; the result is
 * never written back to storage.
 */
export function sanitizeFactionSuggestions(raw: unknown): FactionCandidate[] {
  if (!Array.isArray(raw)) return [];
  return raw.filter(
    (c): c is FactionCandidate =>
      typeof c === "object" &&
      c !== null &&
      typeof (c as { name?: unknown }).name === "string" &&
      (c as { name: string }).name.trim() !== "",
  );
}

/**
 * Sanitize `factionSuggestionSeenNames`: array guard, drop any non-string or
 * blank entry. Read-time only, like every other normalizer in this file; the
 * result is never written back to storage.
 */
export function sanitizeFactionSuggestionSeenNames(raw: unknown): string[] {
  if (!Array.isArray(raw)) return [];
  return raw.filter(
    (name): name is string => typeof name === "string" && name.trim() !== "",
  );
}

/**
 * Reconcile `allies`/`adversaries` references across a faction-list patch
 * against the list it replaces, so a rename or removal made through
 * `update({ factions: [...] })` — the one choke point every wizard surface
 * (StepFactions' candidate toggle, remove, and drawer-save) routes
 * faction-list mutations through — keeps every OTHER faction's relationships
 * consistent, without the caller having to know the old name.
 *
 * Distinguished purely from the name sets, since a patch carries no explicit
 * "this was a rename" signal:
 *   - Exactly one name disappeared and exactly one appeared (same slot,
 *     everything else unchanged) → a rename: rewrite the old name to the new
 *     one everywhere it's referenced.
 *   - One or more names disappeared with no 1:1 replacement (a removal, a
 *     bulk clear, or several at once) → prune every disappeared name from
 *     every remaining faction's references.
 *   - Names only added (selecting a new candidate, adding one manually) →
 *     no removal happened, so references are left untouched.
 */
function cascadeFactionListChange(
  prevFactions: readonly WizardFactionDraft[],
  nextFactions: readonly WizardFactionDraft[],
): WizardFactionDraft[] {
  const prevNames = new Set(prevFactions.map((f) => f.name));
  const nextNames = new Set(nextFactions.map((f) => f.name));
  const removedNames = [...prevNames].filter((n) => !nextNames.has(n));
  const addedNames = [...nextNames].filter((n) => !prevNames.has(n));

  if (removedNames.length === 0) return [...nextFactions];

  if (removedNames.length === 1 && addedNames.length === 1) {
    const [oldName] = removedNames;
    const [newName] = addedNames;
    return nextFactions.map((f) => ({
      ...f,
      allies: f.allies?.map((a) => (a === oldName ? newName : a)),
      adversaries: f.adversaries?.map((a) => (a === oldName ? newName : a)),
    }));
  }

  const removedSet = new Set(removedNames);
  return nextFactions.map((f) => ({
    ...f,
    allies: f.allies?.filter((a) => !removedSet.has(a)),
    adversaries: f.adversaries?.filter((a) => !removedSet.has(a)),
  }));
}

/** Patch shape: any subset of the draft (never `step`/`updatedAt` directly). */
export type WizardDraftPatch = Partial<Omit<WizardDraft, "step" | "updatedAt">>;

/**
 * Read + normalize the persisted draft. Exported for the resume/backfill tests
 * (the module-level `current` is initialized once at load and is not re-read by
 * `__resetWizardDraftForTests`, so legacy-backfill is exercised through here).
 */
export function readDraft(): WizardDraft | null {
  try {
    // One-time cleanup: the v1->v2 key bump orphans a pre-existing v1
    // blob forever unless something deletes it. This is the one path
    // guaranteed to run on every load. A v1 draft is never migrated into v2 —
    // step indices shifted, so old drafts aren't safely portable — just drop
    // the orphan. Isolated in its own try so a removeItem failure (quota/
    // disabled storage) can't break reading the current v2 draft below.
    try {
      localStorage.removeItem(ORPHANED_V1_STORAGE_KEY);
    } catch {
      // ignore (SSR / disabled storage)
    }
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw === null) return null;
    const parsed = JSON.parse(raw) as Partial<WizardDraft>;
    // Defensive: merge over an empty draft so a partial/older payload still
    // yields a fully-shaped draft (forward/backward compatible).
    const empty = createEmptyDraft();
    const merged = { ...empty, ...parsed };
    // Legacy backfill: a pre-fix draft has a numeric `step` but no `visited`.
    // Reconstruct the old "all lower steps done" look ([0..step]) so resumed
    // drafts don't visually regress. (The empty-draft default of [0] only
    // applies when the payload genuinely had no step progress.)
    if (parsed.visited === undefined) {
      merged.visited = Array.from({ length: merged.step + 1 }, (_, i) => i);
    }
    // Sanitize enabledPlatforms: strip pre-rebrand/unknown ids. A payload with
    // no enabledPlatforms at all, a non-array value, or one whose ids were ALL
    // stripped (sanitize -> null) keeps the all-on default from the empty draft
    // above; a deliberately empty array stays empty.
    merged.enabledPlatforms =
      sanitizeEnabledPlatforms(parsed.enabledPlatforms) ??
      empty.enabledPlatforms;
    // Legacy backfill: a pre-fix draft predates `baselineWebsitesChosen`, so a
    // selection the instructor had already pruned would read as "not yet
    // chosen" and get re-seeded to select-all on resume. A non-empty stored
    // selection *is* a deliberate choice.
    if (
      parsed.baselineWebsitesChosen === undefined &&
      merged.baselineWebsiteIds.length > 0
    ) {
      merged.baselineWebsitesChosen = true;
    }

    // Sanitize timelineMode: a retired ("skip") or otherwise unknown value
    // resumes as "" (not yet chosen) so the step reads as Incomplete.
    merged.timelineMode = sanitizeTimelineMode(parsed.timelineMode);

    // Sanitize factions: drop unnamed/blank-named entries and any
    // allies/adversaries reference that no longer resolves to a faction in
    // the (post-drop) list, including self-references.
    merged.factions = sanitizeFactions(parsed.factions);
    // Sanitize factionSuggestions: same array guard + name filter as
    // factions above (see sanitizeFactionSuggestions). A legacy draft
    // predating this field has no key at all, so `parsed.factionSuggestions`
    // is `undefined` and this simply yields `[]` — `readDraft` always
    // returns a defined array here, never leaving the empty-draft default
    // as `undefined`.
    merged.factionSuggestions = sanitizeFactionSuggestions(
      parsed.factionSuggestions,
    );
    // Sanitize factionSuggestionSeenNames: same array guard as
    // factionSuggestions above (see sanitizeFactionSuggestionSeenNames).
    merged.factionSuggestionSeenNames = sanitizeFactionSuggestionSeenNames(
      parsed.factionSuggestionSeenNames,
    );

    // Legacy/cross-source normalization: resolve countryCode from a known
    // persisted code, or back-derive it from `country` (legacy drafts, and
    // drafts written before countryCode existed, only ever had `country`).
    // Unresolvable text is left as an unconfirmed `country` with
    // `countryCode: ""` rather than being blanked — see resolveCountryCode.
    merged.countryCode = resolveCountryCode(
      (parsed as Record<string, unknown>).countryCode,
      merged.country,
    );
    // Legacy/cross-source normalization, mirror of countryCode above: a
    // pre-fix draft (or one written before regionCode existed) only ever
    // had `region` text. Back-derive regionCode from it via the same
    // fold-match lookup `StepLocationObjective.tsx` uses at render time
    // (`resolveRegionCodeFromText`, shared from locationMatch.ts) so a
    // resumed legacy draft is indistinguishable from one that always had a
    // resolved regionCode. No match (unresolvable text, or no subdivision
    // shard for the country) leaves regionCode `null`, same as today.
    if (merged.regionCode == null && merged.region) {
      merged.regionCode = resolveRegionCodeFromText(
        merged.countryCode,
        merged.region,
      );
    }
    return merged;
  } catch {
    return null;
  }
}

function persist(draft: WizardDraft | null): void {
  try {
    if (draft === null) {
      localStorage.removeItem(STORAGE_KEY);
    } else {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(draft));
    }
  } catch {
    // ignore (SSR / disabled storage)
  }
}

// Module-level state shared by all hook instances.
let current: WizardDraft = readDraft() ?? createEmptyDraft();
const listeners = new Set<() => void>();

function emit(): void {
  listeners.forEach((l) => l());
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);

  function onStorage(e: StorageEvent): void {
    if (e.key !== STORAGE_KEY) return;
    current = readDraft() ?? createEmptyDraft();
    emit();
  }
  window.addEventListener("storage", onStorage);

  return () => {
    listeners.delete(listener);
    window.removeEventListener("storage", onStorage);
  };
}

function getSnapshot(): WizardDraft {
  return current;
}

function commit(next: WizardDraft): void {
  current = next;
  persist(next);
  emit();
}

function applyUpdate(patch: WizardDraftPatch): void {
  const merged: WizardDraft = {
    ...current,
    ...patch,
    updatedAt: new Date().toISOString(),
  };
  if (patch.factions !== undefined) {
    merged.factions = cascadeFactionListChange(current.factions, patch.factions);
  }
  commit(merged);
}

function applySetStep(step: number): void {
  const visited = current.visited.includes(step)
    ? current.visited
    : [...current.visited, step];
  commit({ ...current, step, visited, updatedAt: new Date().toISOString() });
}

function applyReset(): void {
  current = createEmptyDraft();
  persist(null);
  emit();
}

/** True when a wizard draft is persisted in storage (drives the resume banner). */
export function hasPersistedDraft(): boolean {
  try {
    return localStorage.getItem(STORAGE_KEY) !== null;
  } catch {
    return false;
  }
}

export interface UseWizardDraft {
  readonly draft: WizardDraft;
  readonly step: number;
  readonly setStep: (i: number) => void;
  readonly update: (patch: WizardDraftPatch) => void;
  readonly reset: () => void;
  readonly hasPersistedDraft: () => boolean;
}

export function useWizardDraft(): UseWizardDraft {
  const draft = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
  const setStep = useCallback((i: number) => applySetStep(i), []);
  const update = useCallback(
    (patch: WizardDraftPatch) => applyUpdate(patch),
    [],
  );
  const reset = useCallback(() => applyReset(), []);
  return {
    draft,
    step: draft.step,
    setStep,
    update,
    reset,
    hasPersistedDraft,
  };
}

/**
 * Reset module state between tests. Re-reads from localStorage so that a test
 * helper that writes to localStorage immediately before calling this function
 * sees the persisted draft on the first getSnapshot() call without needing a
 * storage event trigger.
 */
export function __resetWizardDraftForTests(): void {
  current = readDraft() ?? createEmptyDraft();
  listeners.clear();
}



